  let cell = IMPACT_LIKELIHOOD[impact!][likelihood!];
  if (likelihood! <= 1) cell = Math.min(cell, 2);
  if (rating.regression === "regression" && impact! >= 2 && cell >= 2) cell = Math.min(4, cell + 1);
  return cell;
